def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    if n == 1:
        return 'C' if op[0] == 'C' else 'D'

    opp_c_total = sum(1 for a in op if a == 'C')
    opp_c_rate = opp_c_total / n

    rec_len = 8 if n >= 8 else n
    op_c_rec = sum(1 for a in op[n - rec_len:] if a == 'C')
    op_c_rec_rate = op_c_rec / rec_len

    aCC = aCD = aDC = aDD = 0
    for i in range(1, n):
        prev_my = my[i - 1]
        curr_op = op[i]
        if prev_my == 'C':
            if curr_op == 'C':
                aCC += 1
            else:
                aCD += 1
        else:
            if curr_op == 'C':
                aDC += 1
            else:
                aDD += 1

    start_i = 1 if n <= 11 else n - 10
    rDC = rDD = 0
    for i in range(start_i, n):
        prev_my = my[i - 1]
        curr_op = op[i]
        if prev_my == 'D':
            if curr_op == 'C':
                rDC += 1
            else:
                rDD += 1

    d_total = aDC + aDD
    rd_total = rDC + rDD

    tolerant = False
    if rd_total >= 2:
        if rDC >= 2 and rDC >= 3 * rDD and op_c_rec_rate >= 0.30:
            tolerant = True
        elif rDD == 0 and rDC >= 1 and op_c_rec_rate >= 0.45:
            tolerant = True
    elif d_total >= 1:
        if aDC >= 1 and aDD == 0 and op_c_rec_rate >= 0.40:
            tolerant = True
        elif d_total >= 3 and aDC >= 2 * aDD and aDC >= 2 and opp_c_rate >= 0.50:
            tolerant = True

    last_op = op[-1]

    if n >= 6 and all(x == 'D' for x in op[-6:]):
        if opp_c_rate > 0.45 and rng.random() < 0.08:
            return 'C'
        return 'D'

    if opp_c_rate < 0.20 and op_c_rec_rate < 0.40:
        return 'D'

    if tolerant:
        if aCD > aCC and aCD >= 2:
            return 'D'
        if last_op == 'D':
            if op_c_rec_rate >= 0.25:
                return 'C'
            return 'D'
        return 'D'

    if aCC + aCD >= 5 and aCD > 3 * aCC:
        return 'D'

    if last_op == 'D':
        if n >= 2 and my[-2] == 'D':
            if aCC >= aCD and opp_c_rate >= 0.30:
                return 'C'
            if opp_c_rate >= 0.55 and aCD == 0:
                return 'C'
            return 'D'

        if opp_c_rate > 0.85 and op_c_rec_rate >= 0.75 and aCD <= 1:
            return 'C'
        return 'D'

    if n >= 98 and tolerant:
        return 'D'

    return 'C'
